package ec.edu.scli.reservas.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.time.*; import java.util.UUID; import ec.edu.scli.reservas.domain.model.EstadoSesionAsistencia;
@Entity @Table(name="sesiones_asistencia") public class SesionAsistenciaJpaEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; private UUID reservaId,bloquePlanificacionId,docenteId; private LocalDate fechaClase; private String tokenHash; private Instant abiertaEn,expiraEn,cerradaEn; @Enumerated(EnumType.STRING) private EstadoSesionAsistencia estado=EstadoSesionAsistencia.ABIERTA; public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getReservaId(){return reservaId;} public void setReservaId(UUID v){reservaId=v;} public UUID getBloquePlanificacionId(){return bloquePlanificacionId;} public void setBloquePlanificacionId(UUID v){bloquePlanificacionId=v;} public LocalDate getFechaClase(){return fechaClase;} public void setFechaClase(LocalDate v){fechaClase=v;} public UUID getDocenteId(){return docenteId;} public void setDocenteId(UUID v){docenteId=v;} public String getTokenHash(){return tokenHash;} public void setTokenHash(String v){tokenHash=v;} public Instant getAbiertaEn(){return abiertaEn;} public void setAbiertaEn(Instant v){abiertaEn=v;} public Instant getExpiraEn(){return expiraEn;} public void setExpiraEn(Instant v){expiraEn=v;} public Instant getCerradaEn(){return cerradaEn;} public void setCerradaEn(Instant v){cerradaEn=v;} public EstadoSesionAsistencia getEstado(){return estado;} public void setEstado(EstadoSesionAsistencia v){estado=v;} }
